template<> inline const uestcradar::preview::PreviewFrame *PreviewMessage::payload_as<uestcradar::preview::PreviewFrame>() const {
  return payload_as_PreviewFrame();
}

template<> inline const uestcradar::preview::StreamStatus *PreviewMessage::payload_as<uestcradar::preview::StreamStatus>() const {
  return payload_as_StreamStatus();
}

struct PreviewMessageBuilder {
  typedef PreviewMessage Table;
  flatbuffers::FlatBufferBuilder &fbb_;
  flatbuffers::uoffset_t start_;
  void add_protocol_version(uint16_t protocol_version) {
    fbb_.AddElement<uint16_t>(PreviewMessage::VT_PROTOCOL_VERSION, protocol_version, 1);
  }
  void add_payload_type(uestcradar::preview::MessagePayload payload_type) {
    fbb_.AddElement<uint8_t>(PreviewMessage::VT_PAYLOAD_TYPE, static_cast<uint8_t>(payload_type), 0);
  }
  void add_payload(flatbuffers::Offset<void> payload) {
    fbb_.AddOffset(PreviewMessage::VT_PAYLOAD, payload);
  }
  explicit PreviewMessageBuilder(flatbuffers::FlatBufferBuilder &_fbb)
        : fbb_(_fbb) {
    start_ = fbb_.StartTable();
  }
  flatbuffers::Offset<PreviewMessage> Finish() {
    const auto end = fbb_.EndTable(start_);
    auto o = flatbuffers::Offset<PreviewMessage>(end);
    return o;
  }
};

inline flatbuffers::Offset<PreviewMessage> CreatePreviewMessage(
    flatbuffers::FlatBufferBuilder &_fbb,
    uint16_t protocol_version = 1,
    uestcradar::preview::MessagePayload payload_type = uestcradar::preview::MessagePayload::NONE,
    flatbuffers::Offset<void> payload = 0) {
  PreviewMessageBuilder builder_(_fbb);
  builder_.add_payload(payload);
  builder_.add_protocol_version(protocol_version);
  builder_.add_payload_type(payload_type);
  return builder_.Finish();
}

inline bool VerifyPreviewBody(flatbuffers::Verifier &verifier, const void *obj, PreviewBody type) {
  switch (type) {
    case PreviewBody::NONE: {
      return true;
    }
    case PreviewBody::WaveformPreview: {
      auto ptr = reinterpret_cast<const uestcradar::preview::WaveformPreview *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case PreviewBody::HeatmapPreview: {
      auto ptr = reinterpret_cast<const uestcradar::preview::HeatmapPreview *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyPreviewBodyVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyPreviewBody(
        verifier,  values->Get(i), types->GetEnum<PreviewBody>(i))) {
      return false;
    }
  }
  return true;
}

inline bool VerifyMessagePayload(flatbuffers::Verifier &verifier, const void *obj, MessagePayload type) {
  switch (type) {
    case MessagePayload::NONE: {
      return true;
    }
    case MessagePayload::SidecarHello: {
      auto ptr = reinterpret_cast<const uestcradar::preview::SidecarHello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::SubscriptionUpdate: {
      auto ptr = reinterpret_cast<const uestcradar::preview::SubscriptionUpdate *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::PreviewFrame: {
      auto ptr = reinterpret_cast<const uestcradar::preview::PreviewFrame *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case MessagePayload::StreamStatus: {
      auto ptr = reinterpret_cast<const uestcradar::preview::StreamStatus *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyMessagePayloadVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyMessagePayload(
        verifier,  values->Get(i), types->GetEnum<MessagePayload>(i))) {
      return false;
    }
  }
  return true;
}

inline const uestcradar::preview::PreviewMessage *GetPreviewMessage(const void *buf) {
  return flatbuffers::GetRoot<uestcradar::preview::PreviewMessage>(buf);
}

inline const uestcradar::preview::PreviewMessage *GetSizePrefixedPreviewMessage(const void *buf) {
  return flatbuffers::GetSizePrefixedRoot<uestcradar::preview::PreviewMessage>(buf);
}

inline const char *PreviewMessageIdentifier() {
  return "UPRV";
}

inline bool PreviewMessageBufferHasIdentifier(const void *buf) {
  return flatbuffers::BufferHasIdentifier(
      buf, PreviewMessageIdentifier());
}

inline bool VerifyPreviewMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<uestcradar::preview::PreviewMessage>(PreviewMessageIdentifier());
}

inline bool VerifySizePrefixedPreviewMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<uestcradar::preview::PreviewMessage>(PreviewMessageIdentifier());
}

inline void FinishPreviewMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<uestcradar::preview::PreviewMessage> root) {
  fbb.Finish(root, PreviewMessageIdentifier());
}

inline void FinishSizePrefixedPreviewMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<uestcradar::preview::PreviewMessage> root) {
  fbb.FinishSizePrefixed(root, PreviewMessageIdentifier());
}

